<?php
require '../config/config.php'; role(['administrator','pustakawan']);
$pdo->exec("CREATE TABLE IF NOT EXISTS inventory_categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE) ENGINE=InnoDB");
$pdo->exec("CREATE TABLE IF NOT EXISTS inventories(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(50) UNIQUE NOT NULL,name VARCHAR(150) NOT NULL,category_id INT NULL,location VARCHAR(100),condition_status ENUM('baik','rusak ringan','rusak berat') DEFAULT 'baik',quantity INT DEFAULT 1,notes VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES inventory_categories(id) ON DELETE SET NULL) ENGINE=InnoDB");
if($_SERVER['REQUEST_METHOD']==='POST'){try{$pdo->prepare("INSERT INTO inventories(code,name,category_id,location,condition_status,quantity,notes) VALUES(?,?,?,?,?,?,?)")->execute([trim($_POST['code']),trim($_POST['name']),(int)($_POST['category_id']??0)?:null,trim($_POST['location']),$_POST['condition_status'],max(1,(int)$_POST['quantity']),trim($_POST['notes'])]);setmsg('Inventaris ditambahkan.');}catch(Throwable $e){setmsg('Inventaris tidak dapat disimpan.','danger');}}
$cats=$pdo->query("SELECT * FROM inventory_categories ORDER BY name")->fetchAll();$rows=$pdo->query("SELECT i.*,c.name category_name FROM inventories i LEFT JOIN inventory_categories c ON c.id=i.category_id ORDER BY i.name")->fetchAll();
?><!doctype html><html lang=id><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Inventaris</title><link rel=stylesheet href="../public/style.css"></head><body><div class=layout><?php include '../public/nav.php';?><main class=main><h1>📦 Data Inventaris</h1><?php msg();?><div class=form><form method=post><div class=grid><div><label>Kode Inventaris</label><input name=code required></div><div><label>Nama Barang</label><input name=name required></div><div><label>Kategori</label><select name=category_id><option value="">-- Pilih --</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div><label>Lokasi</label><input name=location></div><div><label>Kondisi</label><select name=condition_status><option>baik</option><option>rusak ringan</option><option>rusak berat</option></select></div><div><label>Jumlah</label><input type=number name=quantity min=1 value=1></div></div><label>Catatan</label><input name=notes><button>+ Simpan Inventaris</button></form></div><br><table class=table><tr><th>Kode</th><th>Nama</th><th>Kategori</th><th>Lokasi</th><th>Kondisi</th><th>Jumlah</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['code'])?></td><td><?=e($r['name'])?></td><td><?=e($r['category_name']??'-')?></td><td><?=e($r['location']??'-')?></td><td><?=e($r['condition_status'])?></td><td><?=$r['quantity']?></td></tr><?php endforeach;?></table></main></div></body></html>